async function flakyApiCall(attemptNumber) {
  // Simulate some computation
  await new Promise(resolve => setTimeout(resolve, 50));

  console.log(`Attempt ${attemptNumber + 1}: Calling the flaky API...`);

  // Fail for the first 3 attempts, succeed on the 4th
  if (attemptNumber < 3) {
    throw new Error(`API call failed on attempt ${attemptNumber + 1}`);
  }

  return `Success! Data retrieved on attempt ${attemptNumber + 1}`;
}

/**
 * Wrapper function that tracks attempt number
 */
let callCount = 0;
async function flakyFunction() {
  const currentAttempt = callCount;
  callCount++;
  return await flakyApiCall(currentAttempt);
}

/**
 * Main function demonstrating retry usage
 */
async function main() {
  console.log('=== acme-retry Example ===\n');
  console.log('Demonstrating retry with 5 attempts and exponential backoff\n');

  // Reset counter for fresh run
  callCount = 0;

  try {
    // Use retry with 5 attempts and 100ms base delay
    const result = await retry(flakyFunction, { 
      attempts: 5, 
      baseMs: 100 
    });

    console.log(`\n✅ Result: ${result}`);
  } catch (error) {
    console.log(`\n❌ All attempts failed: ${error.message}`);
  }

  console.log('\n=== Additional Example: Different Backoff Strategy ===\n');

  // Demonstrate with different configuration
  async function alwaysFails() {
    console.log('This function always fails...');
    throw new Error('Persistent failure');
  }

  try {
    await retry(alwaysFails, { 
      attempts: 3, 
      baseMs: 50 
    });
  } catch (error) {
    console.log(`Expected failure after all retries: ${error.message}`);
  }

  console.log('\n=== Example: Successful on First Try ===\n');

  // Reset counter
  callCount = 0;

  async function reliableFunction() {
    console.log('This function works on the first try!');
    return 'Immediate success';
  }

  const reliableResult = await retry(reliableFunction, { attempts: 5 });
  console.log(`Result: ${reliableResult}`);
}

// Run the example
