async function flakyFunction() {
  callCount++;
  console.log(`Call #${callCount}`);

  // Fail 60% of the time
  if (Math.random() < 0.6) {
    throw new Error(`Failed on attempt ${callCount}`);
  }

  return `Succeeded on attempt ${callCount}`;
}

// Retry the flaky function up to 5 times
async function main() {
  callCount = 0; // Reset counter

  try {
    const result = await retry(flakyFunction, { attempts: 5, baseMs: 100 });
    console.log(`✅ ${result}`);
  } catch (error) {
    console.log(`❌ ${error.message} (after ${callCount} attempts)`);
  }
}

main();

